const ENERGY_CRITICAL_EQUIPMENT = ENERGY_CRITICAL_EQUIPMENT_SOURCE.map(
  (item) => ({
    ...item,
    equipmentType: classifyEquipmentType(item.technicalObjectDescription),
  }),
);

const BY_EQUIPMENT = new Map(
  ENERGY_CRITICAL_EQUIPMENT.map((item) => [normalizeKey(item.equipmentNo), item]),
);

export function getAllEnergyCriticalEquipmentInfo() {
  return ENERGY_CRITICAL_EQUIPMENT;
}

export function getEnergyCriticalEquipmentInfo(equipmentNo: string) {
  return BY_EQUIPMENT.get(normalizeKey(equipmentNo));
}

function normalizeKey(value: string) {
  return value.replace(/[^a-z0-9]/gi, '').toLowerCase();
}

function classifyEquipmentType(value: string) {
  const clean = value.toLowerCase();
  if (clean.includes('coriolis')) return 'Coriolis Flowmeter';
  if (clean.includes('turbine')) return 'Turbine Flowmeter';
  if (clean.includes('thermal mass')) return 'Thermal Mass Flowmeter';
  if (clean.includes('akis eleman')) return 'Akış Elemanı';
  if (clean.includes('flowind') || clean.includes('flow ind')) {
    return 'Flow Indicator';
  }
  if (clean.includes('site_ls') || clean.includes('site-ls')) return 'Site LS';
  if (
    clean.includes('d/p') ||
    clean.includes('dp ') ||
    clean.includes('differantial') ||
    clean.includes('differential')
  ) {
    return 'Diferansiyel Basınç Flow Transmitter';
  }
  return 'Flow Transmitter';
}
